package dev.danielc.fujiapp;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import android.content.Intent;
import androidx.appcompat.app.AppCompatActivity;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

public final class FujiRecipeBook extends AppCompatActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout list;private EditText search;private boolean favorites,closed;private int generation;
 private int dp(int n){return WorkbenchNav.dp(this,n);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(0xffe9ece4);t.setPadding(dp(10),dp(8),dp(10),dp(8));return t;}
 private android.graphics.drawable.GradientDrawable surface(){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(0xff303b37);d.setCornerRadius(dp(14));return d;}
 private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xffd6ed00);b.setTextSize(13);b.setBackground(surface());b.setBackgroundTintList(null);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(46));p.topMargin=dp(8);b.setLayoutParams(p);return b;}
 @Override protected void onCreate(Bundle state){super.onCreate(state);LinearLayout outer=new LinearLayout(this);outer.setBackgroundColor(0xff191c20);LinearLayout root=new LinearLayout(this);root.setPadding(dp(18),dp(8),dp(18),dp(8));root.setOrientation(LinearLayout.VERTICAL);outer.addView(root,new LinearLayout.LayoutParams(-1,-1));setContentView(outer);MainActivity.applyInsets(getWindow(),outer);root.addView(text(getIntent().getBooleanExtra("choose_recipe",false)?"选择配方备注":"我的富士配方",24));root.addView(text("记录自己的机内配方，离线查看与收藏。参数由你填写，拍摄时在相机上设置。",12));Button back=button("‹ 返回创作");root.addView(back);back.setOnClickListener(v->finish());search=new EditText(this);search.setSingleLine(true);search.setTextColor(0xffeef2e5);search.setHintTextColor(0xffa8b5ad);search.setHint("搜索名称、机型、胶片模拟或 C1–C7");root.addView(search);LinearLayout actions=new LinearLayout(this);Button add=button("＋ 新建配方"),filter=button("全部 / 收藏");actions.addView(add,new LinearLayout.LayoutParams(0,dp(46),1));actions.addView(filter,new LinearLayout.LayoutParams(0,dp(46),1));root.addView(actions);add.setOnClickListener(v->edit(null));filter.setOnClickListener(v->{favorites=!favorites;filter.setText(favorites?"★ 仅收藏":"全部 / 收藏");load();});ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){load();}public void afterTextChanged(android.text.Editable e){}});load();}
 private void load(){if(closed)return;final int request=++generation;final String query=search.getText().toString();final boolean onlyFavorites=favorites;worker.execute(()->{List<JSONObject> records=new FujiRecipes(getApplicationContext()).list();runOnUiThread(()->{if(closed||generation!=request)return;list.removeAllViews();int count=0;for(JSONObject r:records)if(FujiRecipes.matches(r,query,onlyFavorites)){count++;LinearLayout tile=new LinearLayout(this);tile.setOrientation(LinearLayout.VERTICAL);tile.setBackground(surface());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);list.addView(tile,p);tile.addView(text((r.optBoolean("favorite")?"★ ":"")+r.optString("title"),19));tile.addView(text(join(r.optString("camera"),r.optString("slot"),r.optString("simulation")),12));if(!r.optString("notes").isEmpty()){TextView note=text(r.optString("notes"),12);note.setMaxLines(2);note.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(note);}tile.setContentDescription("配方 · "+r.optString("title"));tile.setOnClickListener(v->show(r));}if(count==0)list.addView(text(records.isEmpty()?"还没有个人配方。点击新建，把你喜欢的相机设置记录下来。":"没有匹配的配方，可切换筛选或调整搜索词。",14));});});}
 private String join(String... values){StringBuilder s=new StringBuilder();for(String v:values)if(!v.isEmpty()){if(s.length()>0)s.append(" · ");s.append(v);}return s.toString();}
 private void show(JSONObject r){String[] actions=getIntent().getBooleanExtra("choose_recipe",false)?new String[]{"带入当前作品的手动备注","查看参数 / 编辑","收藏或取消收藏","分享参数文字","删除配方"}:new String[]{"查看参数 / 编辑","选照片制作配方签","收藏或取消收藏","分享参数文字","删除配方"};new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(r.optString("title")).setMessage(FujiRecipes.shareText(r)).setPositiveButton("操作",(d,w)->new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(r.optString("title")).setItems(actions,(dialog,index)->{if(actions[index].equals("带入当前作品的手动备注")){setResult(RESULT_OK,new Intent().putExtra("film_note",FujiRecipes.note(r)));finish();}else if(actions[index].equals("选照片制作配方签")){startActivity(new Intent(this,FrameHome.class).putExtra("pick_photo",true).putExtra("frame_style",70).putExtra("recipe_note",FujiRecipes.note(r)));}else if(actions[index].equals("查看参数 / 编辑"))edit(r);else if(actions[index].equals("收藏或取消收藏")){try{r.put("favorite",!r.optBoolean("favorite"));save(r);}catch(JSONException ignored){}}else if(actions[index].equals("分享参数文字")){startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,FujiRecipes.shareText(r)),"分享自己的配方记录"));}else new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("删除此配方？").setMessage("不会删除照片、草稿或作品。").setPositiveButton("删除",(x,y)->worker.execute(()->{new FujiRecipes(getApplicationContext()).delete(r.optString("id"));runOnUiThread(()->{if(!closed)load();});})).setNegativeButton("取消",null).show();}).show()).setNegativeButton("关闭",null).show();}
 private void edit(JSONObject existing){ScrollView scroll=new ScrollView(this);LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);fields.setPadding(dp(16),0,dp(16),0);fields.setBackgroundColor(0xff191c20);scroll.addView(fields);EditText[] inputs=new EditText[FujiRecipes.KEYS.length];for(int i=0;i<inputs.length;i++){fields.addView(text(FujiRecipes.LABELS[i],12));EditText field=new EditText(this);field.setTextColor(0xffeff3e9);field.setBackgroundColor(0xff303b37);field.setPadding(dp(10),dp(12),dp(10),dp(12));field.setHintTextColor(0xff9eaaa0);field.setHint(i==2?"C1–C7，可留空":"留空表示未记录");field.setText(existing==null?(i==1?"X-E5":""):existing.optString(FujiRecipes.KEYS[i]));field.setSingleLine(i!=17);field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(i==17?1000:120)});fields.addView(field);inputs[i]=field;}androidx.appcompat.app.AlertDialog dialog=new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(existing==null?"新建个人配方":"编辑配方记录").setView(scroll).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{if(inputs[0].getText().toString().trim().isEmpty()){inputs[0].setError("请填写名称");return;}String slot=inputs[2].getText().toString().trim().toUpperCase(Locale.ROOT);if(!slot.isEmpty()&&!slot.matches("C[1-7]")){inputs[2].setError("填写 C1–C7 或留空");return;}JSONObject r=new JSONObject();try{r.put("id",existing==null?UUID.randomUUID().toString():existing.getString("id"));r.put("favorite",existing!=null&&existing.optBoolean("favorite"));for(int i=0;i<inputs.length;i++)r.put(FujiRecipes.KEYS[i],i==2?slot:inputs[i].getText().toString().trim());dialog.getButton(-1).setEnabled(false);save(r,success->{dialog.getButton(-1).setEnabled(true);if(success)dialog.dismiss();});}catch(Exception error){Toast.makeText(this,"无法保存配方",Toast.LENGTH_LONG).show();}}));dialog.show();}
 private interface Saved{void done(boolean success);}
 private void save(JSONObject r){save(r,success->{});}
 private void save(JSONObject r,Saved callback){worker.execute(()->{boolean ok=true;try{new FujiRecipes(getApplicationContext()).save(r);}catch(Exception e){ok=false;android.util.Log.w("fuji-recipes","Save failed",e);}final boolean success=ok;runOnUiThread(()->{if(closed)return;Toast.makeText(this,success?"个人配方已保存":"保存失败，请检查存储空间",Toast.LENGTH_LONG).show();callback.done(success);if(success)load();});});}
 @Override protected void onDestroy(){closed=true;worker.shutdown();super.onDestroy();}
}
